export type GetPaymentRequestsData = {
  body?: never;
  path?: never;
  query: {
    /**
     * 事業所ID
     */
    company_id: number;
    /**
     * '申請ステータス(draft:下書き, in_progress:申請中, approved:承認済, rejected:却下, feedback:差戻し)、 取引ステータス(unsettled:支払待ち, settled:支払済み)'<br>
     * approver_id を指定した場合は無効です。
     *
     */
    status?:
      | "draft"
      | "in_progress"
      | "approved"
      | "rejected"
      | "feedback"
      | "unsettled"
      | "settled";
    /**
     * 申請日で絞込：開始日(yyyy-mm-dd)
     */
    start_application_date?: string;
    /**
     * 申請日で絞込：終了日(yyyy-mm-dd)
     */
    end_application_date?: string;
    /**
     * 発生日で絞込：開始日(yyyy-mm-dd)
     */
    start_issue_date?: string;
    /**
     * 発生日で絞込：終了日(yyyy-mm-dd)
     */
    end_issue_date?: string;
    /**
     * 申請No.
     */
    application_number?: number;
    /**
     * 申請タイトル
     */
    title?: string;
    /**
     * 申請者のユーザーID
     */
    applicant_id?: number;
    /**
     * 承認者のユーザーID<br>
     * 'approver_id を指定した場合は、 in_progress: 申請中 の支払依頼のみを返します。'
     *
     */
    approver_id?: number;
    /**
     * 金額で絞込 (下限金額)
     */
    min_amount?: number;
    /**
     * 金額で絞込 (上限金額)
     */
    max_amount?: number;
    /**
     * 取引先IDで絞込
     */
    partner_id?: number;
    /**
     * 取引先コードで絞込
     */
    partner_code?: string;
    /**
     * 支払方法で絞込 (none: 指定なし, domestic_bank_transfer: 国内振込, abroad_bank_transfer: 国外振込, account_transfer: 口座振替, credit_card: クレジットカード)
     */
    payment_method?:
      | "none"
      | "domestic_bank_transfer"
      | "abroad_bank_transfer"
      | "account_transfer"
      | "credit_card";
    /**
     * 支払期限で絞込：開始日(yyyy-mm-dd)
     */
    start_payment_date?: string;
    /**
     * 支払期限で絞込：終了日(yyyy-mm-dd)
     */
    end_payment_date?: string;
    /**
     * 請求書番号で絞込
     */
    document_code?: string;
    /**
     * 部門IDで絞込
     */
    section_id?: number;
    /**
     * 取引先名で絞込
     */
    partner_name?: string;
    /**
     * 申請経路IDで絞込（`/api/1/approval_flow_routes` のレスポンス id と同じ値）
     */
    approval_flow_route_id?: number;
    /**
     * '共有された申請の絞り込み (ignore_observing: 共有された申請を含めない, only_observing: 共有された申請のみ)'
     *
     */
    observing?: "ignore_observing" | "only_observing";
    /**
     * 取得レコードのオフセット (デフォルト: 0)
     */
    offset?: number;
    /**
     * 取得レコードの件数 (デフォルト: 50, 最小: 1, 最大: 500)
     */
    limit?: number;
  };
  url: "/api/1/payment_requests";
};

